/* Each core track has 10 track-specific questions and 5 production incidents. */
const T=(id,num,title,level,short,outcome,tools,explain,concepts,example,usecase,senior,lab,questions,incidents)=>({id,num,title,level,short,outcome,tools,explain,concepts,example,usecase,senior,lab:{title:"Practical lab · "+title,objective:"Apply the skills from this track in a safe, reproducible exercise and capture evidence of the result.",tasks:lab},questions,incidents});
window.CURRICULUM=[
T("linux","01","Linux & Operating Systems","FOUNDATION","Operate the systems that run your workloads.","Navigate Linux, inspect processes, manage services, permissions, storage and logs.","Linux · Ubuntu · RHEL · systemd · SSH · journalctl",
"Linux is the operating-system layer behind most servers, containers and Kubernetes nodes. Learn the filesystem, users/groups, permissions, processes, services, package management, storage, boot and logs. Investigate before changing: capture state, isolate the failure layer, make the smallest reversible fix and verify the real application health.",
[["Filesystem","/etc contains configuration, /var/log logs, /var/lib state, /opt optional application installs, /home user data. Absolute paths begin at root."],["Identity & permissions","Ownership is user:group. File and directory permissions differ. Fix ownership or group access; do not use world-writable permissions as a shortcut."],["Processes & resources","Inspect process tree, CPU, memory, disk, inodes, file descriptors and sockets before terminating a process."],["Services & logs","systemd manages service lifecycle; journalctl exposes logs. A running service can still serve an unhealthy application."]],
"systemctl status employee-app; journalctl -u employee-app -n 100; ss -lntp; df -h; df -i; free -h",
"Deployment failures, disk pressure, service crashes, port conflicts, SSH access and host-level incident response.",
"Preserve evidence before restarting: timestamps, service status, logs, process state, memory, disk/inodes and sockets. Restarting first may hide the cause.",
["Inspect a service and its logs.","Check disk, inodes and memory.","Find the process listening on an application port.","Explain a permission failure using process identity and path ownership.","Propose a reversible fix and a verification command."],
[
["How do absolute and relative paths differ?","Check whether the path begins at the root directory.","An absolute path starts at / and is independent of the current directory. A relative path is resolved from the current working directory.","Portable scripts and deployment paths."],
["Why does directory execute permission matter?","Think about traversing a directory, not running a program.","Execute on a directory allows path traversal/search. Listing names also needs read permission. Parent directories must permit traversal.","Diagnosing permission denied errors."],
["Why is chmod 777 dangerous?","Consider the permissions granted to every local user.","It grants read/write/execute to everyone. Prefer correct ownership, group membership and the narrowest required mode.","Secure application file access."],
["How do you identify the process listening on port 8080?","Use a socket inspection command with process details.","Use sudo ss -lntp and filter port 8080, or lsof. Identify the owner before stopping anything.","Port collision during app deployment."],
["How does a systemd service differ from a process?","One defines managed lifecycle; the other is an executing program.","A process is a running program instance. A service unit defines startup, shutdown, restart, dependencies and environment.","Reliable long-running services."],
["How would you investigate a restart loop?","Read the first failure, exit code and unit configuration.","Inspect systemctl status, journalctl around the first failure, unit overrides, environment, runtime and dependencies.","Post-release startup failures."],
["How can a filesystem run out of inodes while bytes remain?","Many small files consume file entries.","df -h shows byte capacity; df -i shows inode capacity. Find directories generating excessive small files before cleanup.","Log/cache/temp-file storms."],
["Why use named users and sudo instead of direct root SSH?","Think audit trail and blast radius.","Named accounts, key/federated auth, restricted sudo and audited access improve accountability and limit compromise impact.","Production host administration."],
["What should be captured before restarting a service?","Preserve logs and state that may disappear after restart.","Record timestamp, status, recent logs, process tree, resource pressure, socket state, recent changes and endpoint output.","Incident evidence collection."],
["How do you separate host, process and application health?","Check the machine, the process and the user-facing path independently.","Host health covers resources/kernel; process health covers runtime state; application health covers real dependency and endpoint behaviour. All three matter.","Layered service diagnosis."]
],
[
["Disk full","SEV-2","Writes fail and /var is 100% full.","Check df bytes and inodes; inspect largest paths, log rotation and application write patterns.","Clean only confirmed disposable data or expand through change control; validate writes and add disk/inode alerts."],
["systemd restart loop","SEV-2","A release starts then exits repeatedly.","Inspect first failure, exit code, service user, environment and runtime version.","Rollback if change-related, fix root cause and validate endpoint plus restart count."],
["Permission denied after deploy","SEV-3","Application cannot read its new configuration.","Check process identity, file owner/group/mode and every parent directory.","Grant only required access and verify as the service account, not root."],
["Port collision","SEV-3","Application fails to bind port 8080.","Identify the listening PID and its service ownership before stopping it.","Stop the correct managed service or change declared port; confirm intended listener."],
["SSH outage","SEV-2","Operators cannot access hosts after hardening.","Check network route, firewall, sshd, authentication logs and account/key state.","Use approved break-glass access, restore minimal access and verify non-root login."]
]),
T("shell","02","Shell, Bash & Python Automation","FOUNDATION","Turn repeatable operations into safe automation.","Write robust scripts with validation, error handling, logs and idempotency.","Bash · PowerShell · Python · jq · yq · cron",
"Automation is not just a list of commands. Production scripts validate inputs, quote paths, handle exit codes, log useful context, avoid leaking credentials and are safe to rerun. Bash is strong for host-level command composition; Python is often better for APIs, structured data, reusable logic and testing.",
[["Shell streams","Understand variables, quoting, stdin/stdout/stderr, exit status, pipes, globs and command substitution."],["Safe changes","Validate arguments, use allow-lists, support dry-run for destructive operations and avoid unsafe string concatenation."],["Python operations","Use argparse, pathlib, logging, requests, exceptions and virtual environments. Handle pagination and rate limits."],["Testing & scheduling","Test success and failure paths, prevent overlapping runs and make jobs idempotent."]],
"set -euo pipefail; test -d \"$TARGET\" || exit 2; find \"$TARGET\" -type f -mtime +14 -print",
"Deployment automation, health checks, backup jobs, API integrations, cloud inventory and operational utilities.",
"A script that exits zero after silently ignoring a failed command is worse than no automation. Define success precisely and test negative paths.",
["Accept a service name and URL; validate both.","Check a service and endpoint without assuming root.","Use meaningful non-zero exit codes.","Write timestamped logs without printing secret values.","Add dry-run behaviour for cleanup."],
[
["What is the difference between stdout and stderr?","Think normal result versus diagnostic output.","stdout carries normal output; stderr carries diagnostics. They can be redirected separately so pipelines consume results without swallowing errors.","CI logs and scheduled scripts."],
["Why quote shell variables?","Test a file path containing spaces and wildcard characters.","Quoting prevents word splitting and glob expansion. Quote scalar paths and use arrays for argument lists.","Safe file and deployment operations."],
["What does exit code zero mean?","A process reports status to its caller.","Zero conventionally means success; non-zero means failure. A pipeline must preserve failure status for CI to stop correctly.","Pipeline quality gates."],
["What is idempotency?","Consider running the same operation twice.","Repeating the operation yields the same desired state without duplicate or unintended effects. Check current state before mutation.","Configuration and deployment automation."],
["Why add dry-run mode?","Preview intended targets before destructive mutation.","A dry-run lists the exact scope and planned action without changing state, enabling review and safer operations.","Cleanup, migrations and cloud maintenance."],
["When is Python better than Bash?","Think structured JSON, APIs and reusable logic.","Python offers stronger data structures, API libraries, exceptions and unit testing for complex automation. Bash is ideal for short command glue.","Cloud inventory and platform tools."],
["How should an API script handle HTTP 429?","Respect provider backpressure instead of retrying immediately.","Use Retry-After, bounded exponential backoff with jitter, request limits and retries only for safe operations.","GitHub and cloud API clients."],
["Why is set -e not sufficient error handling?","Some commands are intentionally allowed to fail in conditions or pipelines.","Its behaviour has edge cases. Explicitly check critical return codes, use pipefail where suitable and define recovery paths.","Reliable shell automation."],
["How do you prevent overlapping scheduled jobs?","A slow job may still be active when the next schedule fires.","Use a lock/lease, scheduler concurrency policy, timeouts and stale-lock recovery. Make the task idempotent as a second defence.","Backups and recurring cleanup."],
["What should an operations script test?","Include invalid input and dependency failure, not just the happy path.","Test normal execution, boundaries, missing tools, network failure, permission denial, repeated execution and destructive-scope protection.","Pre-merge script testing."]
],
[
["Cleanup script targets wrong directory","SEV-1","A cron job deletes files outside intended retention scope.","Stop future runs, preserve logs, identify exact paths and assess backup recovery.","Disable job, restore verified data, add path allow-list and test dry-run in disposable directories."],
["Pipeline hides command failure","SEV-1","A script prints success after a failed deployment command.","Inspect exit codes, pipelines, redirects and conditional branches.","Propagate errors and add a deliberately failing test to prove the pipeline blocks."],
["API retry storm","SEV-2","A client multiplies traffic after 429 and timeout responses.","Inspect retry count, concurrency, response headers and idempotency.","Add bounded backoff, jitter, Retry-After and metrics; stop retrying unsafe writes."],
["Scheduled job overlaps","SEV-2","Two cleanup processes race on the same files.","Inspect scheduler history, process duration and lock behaviour.","Add a lock/concurrency rule and test stale-lock recovery."],
["Token appears in logs","SEV-1","Debug output prints an API credential.","Find exposure window, log readers and external exports.","Revoke and rotate token, remove unsafe logging, add masking and secret scanning."]
]),
T("git","03","Git & Engineering Workflow","FOUNDATION","Collaborate safely through version control.","Use branches, commits, remotes, reviews, tags, conflict resolution and release workflows.","Git · GitHub · GitLab · CODEOWNERS",
"Git records source history so changes can be reviewed, reproduced and rolled back. Learn the working tree, index, commits, branches, remotes, merge/rebase, tags and conflicts. A professional workflow connects each change to a reason, uses focused commits, protects main and runs checks before merge. Keep secrets, state and generated credentials out of history.",
[["Working tree & index","Stage intended files with git add and inspect staged content before commit."],["Branches & remotes","A branch is a movable commit reference. A remote such as origin maps a local name to another repository."],["Merge & rebase","Merge joins histories; rebase replays commits. Resolve conflicts intentionally and run tests afterwards."],["Review & release","Use protected branches, required checks, CODEOWNERS and meaningful tags. Revert shared production history safely."]],
"git switch -c feature/health; git add src; git diff --cached; git commit -m \"feat: add health endpoint\"; git push -u origin feature/health",
"Source collaboration, infrastructure code review, release provenance and safe production rollback.",
"Treat history as an audit trail. Prefer revert for shared branches. Never commit Terraform state, kubeconfigs, private keys or credentials.",
["Inspect staged versus unstaged changes.","Create a focused branch and commit.","Explain origin and upstream tracking.","Resolve a merge conflict and validate the result.","Describe a safe production rollback."],
[
["What does git add do?","It changes the index, not the commit history.","It stages selected content in the index. git commit records the staged snapshot as a new commit.","Reviewable changes."],
["What is origin?","It is a conventional remote name, not a special Git keyword.","Origin usually names the remote repository cloned from. A repository can have multiple remotes.","Fork plus upstream workflows."],
["What does git push -u origin feature/x do?","Think about the next push and pull command.","It pushes the branch and sets its upstream tracking branch so later push/pull can infer the remote.","First push of a feature branch."],
["When is git revert safer than git reset?","Has the commit already been shared?","Revert adds a new commit that inverses an earlier one while preserving shared history. Reset moves a branch pointer and can rewrite history.","Production rollback."],
["How do merge and rebase differ?","Consider whether the history contains a merge node.","Merge joins branches and may create a merge commit. Rebase replays commits onto another base to create a linear history.","Maintaining feature branches."],
["How should conflicts be resolved?","Do not blindly choose ours or theirs.","Understand both changes, edit the intended combined result, stage it and run tests before completing merge/rebase.","Concurrent manifest edits."],
["Why should Terraform state not be committed?","It is environment-specific and may contain sensitive values.","Store state in a secured remote backend with encryption, locking and access controls. Git should contain configuration.","Team IaC workflow."],
["What is a protected branch?","It enforces policy before code lands.","Rules can require reviews, status checks, signed commits or restricted pushes, preventing unreviewed changes.","Main and release branches."],
["Why use tags for releases?","A tag points to a specific source commit.","Tags identify release commits; annotated or signed tags provide additional metadata and authenticity.","Reproducible release references."],
["What belongs in a pull request description?","A reviewer needs reason, evidence, risk and recovery.","Explain problem, change, tests, deployment/migration impact, security/cost considerations and rollback plan.","Auditable engineering change."]
],
[
["Force push removes shared commits","SEV-2","A shared branch moved backwards.","Stop pushes; inspect reflogs and remote refs to identify the last valid SHA.","Coordinate branch restoration and educate on force-with-lease and shared history."],
["Credential committed publicly","SEV-1","A cloud token appears in repository history.","Treat it as compromised; identify permissions, exposure window and usage.","Revoke/rotate first, audit usage, remediate history and enable push protection."],
["Bad merge causes outage","SEV-1","A release after a PR returns errors.","Correlate deployment SHA and time with metrics; inspect diff and dependency changes.","Revert or redeploy known-good artifact, then add a regression test."],
["Required CI check bypassed","SEV-2","An unreviewed change merged despite failing validation.","Inspect branch rules, bypass actors, check source and audit events.","Restore required rules and test that a deliberately failing PR is blocked."],
["Release tag points to wrong source","SEV-2","Published binary does not match reviewed SHA.","Compare tag SHA, build metadata and artifact digest.","Publish a corrected immutable version and require provenance verification."]
]),
T("network","04","Networking, DNS, HTTP & TLS","FOUNDATION","Trace traffic from client to workload.","Understand addressing, routing, DNS, HTTP, TLS, proxies and load balancers.","TCP/IP · DNS · HTTP · TLS · curl · dig",
"Every service depends on a network path. Diagnose in layers: name resolution, routing, security controls, TCP handshake, TLS negotiation, HTTP response and application dependency. A timeout, connection refusal and HTTP 500 are different failure classes. Learn CIDR, gateways, NAT, DNS record types and TTL, certificates, reverse proxies and load balancing.",
[["Addressing & routing","CIDR defines ranges. Route tables select the next hop; gateways, NAT and peering affect reachability."],["DNS","A/AAAA map names to IPs; CNAME aliases names; TXT supports verification/policy. TTL controls caching."],["HTTP & proxies","Methods, headers, status codes, reverse proxies and load balancers shape traffic."],["TLS & diagnosis","Check certificate identity, chain, expiry, SNI and time. Use dig, curl, openssl and socket tools."]],
"dig +short api.example.com; curl -v https://api.example.com/health; openssl s_client -connect api.example.com:443 -servername api.example.com",
"Service reachability, TLS expiry, DNS cutovers, VPC connectivity, ingress and latency diagnosis.",
"Timeout means no timely response; refused means an endpoint rejected the connection; 503 is an HTTP response. Follow the failing layer instead of restarting blindly.",
["Resolve hostname and inspect TTL.","Test TCP reachability and route assumptions.","Inspect TLS identity and expiry.","Interpret HTTP status and latency.","Write a hop-by-hop fault isolation summary."],
[
["How does connection refused differ from timeout?","One is an active rejection; one receives no timely reply.","Refused usually means destination or intermediary actively rejected the connection. Timeout means a response did not arrive in time.","Listener versus routing/firewall diagnosis."],
["What does DNS TTL control?","Think how long recursive resolvers cache records.","TTL is the cache lifetime of a DNS record. Lowering it ahead of planned change can reduce cache duration but does not create instant global propagation.","DNS migration."],
["Which record maps a hostname to IPv4?","Compare A and AAAA.","A maps a name to IPv4; AAAA maps a name to IPv6.","Public DNS records."],
["What does 502 usually indicate?","The gateway cannot obtain a valid upstream response.","A 502 commonly means a proxy received an invalid response from an upstream server. Check protocol, upstream health and resets.","Reverse proxy and ingress."],
["What does HTTP 503 mean?","The service cannot currently handle the request.","503 indicates temporary unavailability, overload, maintenance or no healthy upstream targets.","Load balancer troubleshooting."],
["Why does TLS SNI matter?","One address can host multiple HTTPS virtual hosts.","SNI lets a client tell the server the requested hostname during TLS negotiation so the correct certificate can be selected.","Wrong certificate on shared ingress."],
["What are SAN and certificate expiry?","The cert must cover the requested hostname and current time.","Subject Alternative Names list hostnames the certificate covers. Expired certificates are invalid; also inspect chain and clock.","TLS trust failures."],
["What does a reverse proxy do?","It sits between clients and upstream application servers.","It can route requests, terminate TLS, cache, authenticate, compress and load balance traffic.","API gateway and ingress."],
["What is CIDR notation?","The slash number is the network prefix length.","CIDR such as 10.0.1.0/24 represents an address range determined by prefix bits.","Subnet planning."],
["How do you separate DNS and application failure?","Resolve the hostname, then test the target preserving Host/SNI.","Use dig and curl; compare resolver answers and optionally test a known IP with curl --resolve. Then inspect proxy and application health.","Layered diagnostics."]
],
[
["DNS cache sends traffic to old system","SEV-2","Some users resolve the old IP after cutover.","Check authoritative records, TTL, resolver caches and regional differences.","Keep overlap, verify new target health and wait out cache expiry."],
["TLS certificate expires","SEV-1","Clients fail handshake on all endpoints.","Inspect expiry, SAN, chain, SNI and renewal automation.","Renew and deploy valid cert; test from multiple clients and alert ahead of expiry."],
["Load balancer returns 502","SEV-1","Proxy logs show upstream reset.","Check target health, port/protocol, app readiness, security policy and timeout mismatch.","Restore healthy targets or roll back incompatible release and test end-to-end."],
["Only one subnet times out","SEV-2","Instances in one subnet cannot reach a dependency.","Compare route tables, NACLs, security groups, DNS, NAT and flow logs.","Fix the narrow missing rule and test both traffic directions."],
["Latency spikes while errors remain low","SEV-2","Requests succeed but p95 doubles.","Break down DNS/connect/TLS/proxy/upstream/database time and saturation.","Relieve bottleneck, verify percentiles and avoid masking with excessive timeouts."]
]),
T("build","05","SDLC, Build Systems & Artifacts","FOUNDATION → INTERMEDIATE","Create repeatable and traceable application releases.","Understand build lifecycles, dependencies, packaging, versioning and artifacts.","Maven · Gradle · npm · pip · Nexus · Artifactory · SBOM",
"A delivery pipeline turns source into an artifact that can be tested, stored, promoted and deployed. Learn dependency resolution, compilation, unit/integration tests, packaging and semantic versioning. Keep build and runtime concerns separate. Artifacts should be immutable and identified by version and digest; promote the same tested binary through environments rather than rebuilding it.",
[["Build lifecycle","Understand resolve, compile, test, package and verify phases and what each proves."],["Dependencies","Review direct and transitive packages, lock versions deliberately and use trusted registries."],["Artifact repositories","Store immutable JARs, packages and images with access controls, retention and metadata."],["Provenance","Record source SHA, build workflow, tests, dependency metadata, signer and digest."]],
"mvn --batch-mode clean verify; sha256sum target/*.jar; java -jar target/app.jar",
"Java/Maven delivery, package integrity, dependency governance, artifact rollback and release traceability.",
"Never deploy whichever file happens to be in a build directory. Record source commit, build run, artifact version and digest; promote the exact tested artifact.",
["Run a clean build and inspect tests.","Inspect direct and transitive dependencies.","Generate immutable artifact version and checksum.","Record source commit and build metadata.","Describe promotion and rollback using the same artifact."],
[
["Why promote the same artifact across environments?","Rebuilding can change dependencies, timestamps or source.","Promoting preserves tested bytes and reduces differences between staging and production.","Staging to production release."],
["What is a transitive dependency?","It is brought in by another package.","A package required by a direct dependency; it may introduce vulnerabilities or version conflicts.","Software composition analysis."],
["How does a JAR differ from a container image?","One is an archive; the other a runtime filesystem and metadata.","A JAR packages Java classes/resources. A container image packages a filesystem and launch metadata, potentially including the JAR and runtime.","Java packaging."],
["Why are release versions immutable?","The same version should always identify the same bytes.","Overwriting a version makes rollback and audit ambiguous. Publish a new version and compare digests.","Artifact repository governance."],
["What does a SHA-256 digest prove?","It allows content equality verification.","It verifies bytes match an expected digest; it does not prove who built them without trusted signing/provenance.","Artifact validation."],
["What is an artifact repository for?","It distributes build outputs, not source history.","It stores versioned packages/images with access control, caching, retention and metadata.","Shared dependency and release storage."],
["Why use a lockfile?","It captures a resolved dependency graph.","A lockfile improves repeatability by pinning concrete dependency versions; changes should be reviewed.","npm/Python applications."],
["How do unit and integration tests differ?","One isolates components; one checks interactions.","Unit tests validate small units in isolation. Integration tests verify collaboration with databases or services.","CI test strategy."],
["What does semantic versioning communicate?","Think major, minor and patch compatibility.","Major signals breaking changes; minor adds compatible features; patch adds compatible fixes, subject to project policy.","API/package versioning."],
["What evidence should accompany a release?","Connect source, build, tests, dependency and final bytes.","Record source SHA, builder identity, test evidence, SBOM, artifact digest, signature and approval/deployment metadata.","Audit and rollback."]
],
[
["Artifact overwritten under same version","SEV-1","Different JARs exist for one release coordinate.","Compare digest, publication time, build ID and consuming deployments.","Stop promotion, publish new immutable version and enforce repository immutability."],
["CI passes but runtime cannot start","SEV-2","Production JAR fails under deployed Java runtime.","Compare Java versions, profiles, environment, packaging and dependencies.","Reproduce with runtime image, add startup test and roll back if users are affected."],
["Dependency update causes regression","SEV-2","Transitive library update changes behaviour.","Inspect dependency tree/lockfile and reproduce with focused test.","Pin compatible version, add regression coverage and update in reviewed change."],
["Deployment cannot retrieve artifact","SEV-1","Repository returns 403 or 404.","Check coordinates, version, endpoint, identity policy, expiry and network.","Restore least-privilege read access or correct coordinates; never hardcode long-lived keys."],
["Deployed binary differs from reviewed source","SEV-1","Release metadata points to an unexpected commit.","Trace workflow run, artifact digest, provenance and manual upload path.","Redeploy verified artifact and enforce provenance checks before promotion."]
]),
T("cicd","06","CI/CD & Release Engineering","INTERMEDIATE","Automate the path from commit to production.","Build secure pipelines with quality gates, approvals and safe deployment strategies.","GitHub Actions · Jenkins · GitLab CI · Azure Pipelines · OIDC",
"CI validates small changes frequently. Continuous Delivery keeps software deployable; Continuous Deployment automatically releases qualifying changes. Build pipelines as code with least-privilege identities, pinned actions/plugins, isolated jobs, artifact handoff, security gates and approvals. Deployment success must be measured by actual health, not only a successful shell command.",
[["Pipeline structure","Separate build, test, scan, package, publish and deploy concerns; pass immutable artifacts between jobs."],["Triggers & concurrency","Understand push/PR/manual/scheduled triggers, branch filters, path filters, environments and concurrency groups."],["Identity & secrets","Prefer short-lived OIDC roles to long-lived keys. Scope permissions per job and never print credentials."],["Release strategies","Rolling, blue/green and canary deployments trade speed, resources and rollback behaviour. Gate traffic on health."]],
"name: verify; on: pull_request; permissions: contents: read; jobs: test: runs-on: ubuntu-latest; steps: checkout; mvn clean verify",
"Automated testing, infrastructure validation, release approvals, canary analysis and auditable deployments.",
"Workflow files are privileged code. Pin actions where feasible, narrow OIDC trust claims and require post-deployment validation through the production route.",
["Define PR triggers and concurrency behaviour.","Grant read-only permission to validation job.","Add formatting, unit and security gates.","Publish immutable artifact and digest.","Design protected deployment approval and OIDC role trust."],
[
["How do CI, delivery and deployment differ?","Think whether production release has a human approval step.","CI integrates and validates changes. Continuous Delivery keeps releases ready, often with approval. Continuous Deployment automatically releases eligible changes.","Selecting delivery governance."],
["Why pass artifacts between jobs?","Avoid rebuilding different content later.","Artifact handoff preserves the tested output for scanning and deployment.","Build once, deploy many."],
["What is a GitHub Actions runner?","It executes workflow jobs.","A hosted runner is managed by GitHub; a self-hosted runner needs isolation, patching, cleanup and trust-boundary controls.","CI execution environment."],
["Why is OIDC safer than stored cloud keys?","Think lifetime and secret distribution.","OIDC exchanges a workload identity token for temporary cloud credentials. Trust conditions must be narrowly restricted.","GitHub-to-AWS role assumption."],
["What is a quality gate?","A condition that blocks further promotion until satisfied.","Tests, scans, policy checks, approvals or health metrics can gate the next stage. Failure should stop promotion and explain why.","Release safety."],
["Why use workflow concurrency?","Two runs may attempt to deploy the same environment.","Concurrency can serialize or cancel overlapping runs; choose carefully so a production rollout is not left partially applied.","Deployment race prevention."],
["What is the risk of privileged workflows on untrusted PR code?","The PR may execute attacker-controlled commands.","Untrusted code can exfiltrate secrets or use write tokens. Separate fork validation from trusted publishing and avoid unsafe trigger contexts.","Public repository CI security."],
["How does canary deployment reduce risk?","Expose a small traffic portion before expanding.","Canary shifts limited traffic to the new version and expands only if error/latency signals remain acceptable.","Production release strategy."],
["What should post-deployment validation test?","A running process does not guarantee a working service.","Check readiness, user-facing endpoints, critical transactions, error rate, latency and dependencies.","Deployment acceptance."],
["How should rollback be designed?","Know the previous artifact and trigger before release.","Use immutable known-good artifact, automated health gate, traffic reversal and backward-compatible schema changes. Test rollback.","Reliable release operations."]
],
[
["PR workflow leaks a secret","SEV-1","Privileged token is exposed to fork-controlled code.","Identify trigger, token permissions and possible secret access.","Revoke credentials, separate untrusted validation from publishing and add workflow policy tests."],
["Two deployments race","SEV-1","Two workflow runs update the same environment.","Compare timestamps, live versions and partial rollout state.","Freeze promotion, reconcile to one version and enforce environment concurrency."],
["Pipeline green while users see 503","SEV-1","Deploy commands succeed but application is unhealthy.","Inspect target health, real route, app startup and whether a meaningful health gate exists.","Stop traffic shift or rollback; require endpoint and synthetic validation."],
["Self-hosted runner compromised","SEV-1","Unexpected process and persistent credentials appear.","Isolate runner; inspect job history, filesystem, egress and exposed identities.","Rebuild ephemeral runner, rotate tokens and isolate jobs by trust level."],
["Workflow cancelled during rollout","SEV-2","A newer run cancelled the previous deployment mid-change.","Inspect orchestrator state, active targets and data compatibility.","Stabilize one release, complete or reverse rollout and define safe queue/cancel policy."]
]),
T("containers","07","Containers & Image Supply Chain","INTERMEDIATE","Package apps into portable, secure runtime units.","Build optimized images, operate containers safely and manage networks/volumes.","Docker · Podman · BuildKit · Compose · Trivy · ECR · GHCR",
"Containers package an application filesystem and dependencies while sharing the host kernel. Learn images/layers, runtime instances, networking, volumes, registries, health and resource limits. Build reproducible images with multi-stage stages, pinned bases and non-root users. Containers are not automatically secure or highly available; platform and orchestration controls remain necessary.",
[["Images & layers","Images are immutable layer sets; containers are runtime instances with writable state."],["Dockerfile quality","Use multi-stage builds, specific base versions, small runtime dependencies and a non-root user."],["Networking & persistence","Published ports expose container services; networks connect containers; volumes persist data beyond container lifetime."],["Hardening","Drop capabilities, avoid privileged mode, set resource limits, scan/sign images and inject secrets at runtime."]],
"docker build -t employee-api:1.0.0 .; docker run --rm -p 8080:8080 employee-api:1.0.0; docker logs CONTAINER",
"Consistent CI environments, microservice packaging, application portability and artifact supply-chain controls.",
"Never bake credentials into an image layer; deleting them in a later layer does not remove the earlier bytes. Inject secrets at runtime and scan the final image.",
["Write a multi-stage Java Dockerfile.","Pin the runtime base and run non-root.","Build and inspect the final image.","Run with controlled ports and resource limits.","Scan the final digest and document findings."],
[
["How does image differ from container?","One is template; one is running instance.","An image is an immutable filesystem/metadata template; a container is an isolated runtime instance created from it.","Container lifecycle."],
["Why use multi-stage builds?","Keep compilers out of the runtime image.","Build tools stay in an intermediate stage; only required output is copied into the final runtime image.","Smaller Java and Node images."],
["Why run as non-root?","Consider actions possible after application compromise.","Non-root reduces container privileges. Combine with dropped capabilities and read-only filesystem where possible.","Runtime hardening."],
["What is EXPOSE versus -p?","One documents a port; one publishes it.","EXPOSE is image metadata. docker run -p maps a host port to a container port.","Local networking."],
["Why use volumes?","Container writable layers are ephemeral.","Volumes persist data independently of a container instance; stateful data still needs backup and recovery.","Database persistence."],
["Why pin base image by digest?","A mutable tag can resolve to changed bytes.","A digest identifies exact image content and improves reproducibility; schedule controlled updates for security fixes.","Build trust."],
["Why set CPU/memory limits?","A noisy workload can exhaust shared host resources.","Limits constrain resource usage; right-size from measurements to avoid starvation or OOM.","Multi-tenant systems."],
["Why does deleting a secret in a later Docker layer not solve leakage?","Earlier immutable layers can still contain it.","Image history/layers may retain secret bytes. Rebuild from a clean base and rotate exposed credentials.","Supply-chain incident."],
["What does a container registry provide?","Storage and distribution of versioned image manifests/layers.","A registry controls access, retention, scanning and integration with signing/provenance tools.","CI-to-cluster delivery."],
["What do you inspect when a container exits immediately?","Check logs, exit code and startup contract.","Inspect previous logs, entrypoint, env/config, permissions, mounts and dependencies using the same image digest.","Crash-loop investigation."]
],
[
["Container exits at startup","SEV-2","Runtime repeatedly restarts with exit code 1.","Inspect logs, entrypoint, env vars, mounts and identity.","Correct contract or roll back image; validate using exact digest."],
["Image suddenly grows","SEV-3","Routine build is much larger than before.","Inspect layer history, build context, copied caches and multi-stage boundaries.","Use .dockerignore and copy only runtime artifacts."],
["DNS works but DB connection times out","SEV-2","Container resolves DB name but TCP fails.","Check network attachment, port, security rules, route and database listener.","Fix narrow network path and test from workload namespace."],
["Approved tag now refers to new bytes","SEV-1","Deployment pulled changed content under mutable tag.","Compare registry manifest digests and pull policy.","Pin digest, promote immutable image and verify signature."],
["Overprivileged container exploited","SEV-1","Runtime alert shows host-level access attempt.","Inspect privileged flag, host mounts, capabilities and namespaces.","Isolate, rotate secrets, rebuild cleanly and enforce restricted runtime policy."]
]),
T("k8s","08","Kubernetes, Helm & Cloud Native","ADVANCED","Operate resilient workloads on a container platform.","Understand cluster architecture, scheduling, workloads, networking, probes, storage and RBAC.","Kubernetes · kubectl · Helm · Kustomize · EKS · AKS · GKE",
"Kubernetes is declarative orchestration: you describe desired state and controllers reconcile actual state. Learn control plane/worker nodes, Pods, Deployments, Services, Ingress, probes, requests/limits, autoscaling, storage, Secrets, RBAC and network policies. Debug with Events and describe output before deleting resources; a Pod failure may be a symptom of scheduling, storage, network or node conditions.",
[["Control plane & reconciliation","API server stores objects; controllers reconcile; scheduler places Pods; kubelet manages node containers."],["Workloads & networking","Deployments manage replicas; Services provide stable discovery; Ingress/Gateway routes external traffic."],["Health & resources","Startup, readiness and liveness probes differ. Requests shape scheduling; limits constrain runtime use."],["Security & storage","Restrict RBAC, protect Secrets, use service accounts/network policies and persistent volumes for state."]],
"kubectl get pods -A; kubectl describe pod NAME; kubectl logs NAME --previous; kubectl rollout status deployment/api",
"Cloud-native microservices, declarative rollouts, service discovery, self-healing and managed cluster operations.",
"Read Events and describe output before deleting Pods. Inspect image pull, probes, scheduling, mounts, quotas and node conditions; deletion may erase evidence.",
["Deploy app with Deployment and Service.","Set requests/limits and three probe types appropriately.","Inspect rollout status and events.","Inject a bad image or probe and find the cause.","Roll back and verify service health."],
[
["Pod versus Deployment?","Smallest scheduled unit versus controller managing replicas.","A Pod runs containers. Deployment manages ReplicaSets and desired replicas, rollout and rollback.","Stateless workload operations."],
["What does a Service provide?","Pods are ephemeral; clients need stable discovery.","A Service exposes a stable endpoint and routes to selected ready Pods.","Service-to-service calls."],
["Readiness versus liveness?","One gates traffic; one restarts stuck containers.","Readiness controls traffic eligibility. Liveness triggers restart when the container is unhealthy.","Avoid traffic to broken replicas."],
["Why use a startup probe?","Protect slow-starting applications from early liveness failures.","Startup probe gives an app time to initialize before liveness/readiness checks take effect.","Slow Java startup."],
["Requests versus limits?","Scheduling uses requests; runtime enforces limits.","Requests influence placement. Limits cap CPU/memory; memory breach can cause OOMKilled and CPU can throttle.","Capacity and noisy-neighbour control."],
["What causes CrashLoopBackOff?","It describes repeated container failures, not root cause.","The process exits or fails liveness repeatedly. Inspect previous logs, exit code, config, deps and probes.","Release diagnosis."],
["What causes ImagePullBackOff?","The node cannot retrieve the image.","Check image/tag/digest, registry access, imagePullSecrets, DNS/network and architecture.","Private registry."],
["What does a namespace provide?","Logical grouping and scoped policies, not complete isolation.","Namespaces organize objects and enable quota/RBAC policy; they are not by themselves a complete security boundary.","Team/platform organization."],
["Why restrict Kubernetes Secret access?","API access can expose credentials.","Use least-privilege RBAC, encryption at rest, rotation and external secret delivery where appropriate.","Workload credentials."],
["How do you safely roll back a Deployment?","Check rollout history and data compatibility.","Use rollout status/history and undo to a known-good revision, then validate readiness and user-facing service health.","Bad release recovery."]
],
[
["Pods remain Pending","SEV-2","FailedScheduling events appear.","Inspect requests, node capacity/taints, affinity, PVC binding and quotas.","Correct capacity or constraints; verify placement without blindly lowering requests."],
["CrashLoopBackOff after release","SEV-1","New version exits after startup.","Inspect previous logs, exit code, config, secrets and probe timing.","Roll back if change-related, fix cause and verify restart count and SLI."],
["Service has no endpoints","SEV-1","ClusterIP exists but traffic fails.","Compare selectors/labels, Pod readiness and targetPort.","Fix selector or readiness and verify EndpointSlices contain healthy targets."],
["OOMKilled under traffic","SEV-2","Memory usage climbs and Pods restart.","Compare working set, memory limit, Java heap/native memory and concurrency.","Protect capacity, right-size from evidence and profile suspected leak."],
["Node becomes NotReady","SEV-1","Several unrelated workloads fail on one worker.","Inspect kubelet/runtime, disk and memory pressure, network and instance health.","Cordon/drain only after checking PDB and capacity; recover and validate rescheduling."]
]),
T("iac","09","Infrastructure as Code & Configuration","ADVANCED","Version, review and reproduce infrastructure.","Build modular infrastructure with safe state, plan review and drift handling.","Terraform · OpenTofu · Ansible · Packer · CloudFormation · Checkov",
"IaC describes infrastructure in reviewable code. Terraform/OpenTofu use providers, resources, data sources, variables, outputs, modules and state. State maps config to live resource identity and must be protected and locked. Learn plans, dependencies, imports, drift, lifecycle, remote backends and policy checks. Ansible configures systems; Packer builds machine images.",
[["Resources & graph","Providers expose resource types; resources manage objects; data sources read; references form dependency graph."],["State & lifecycle","State maps configuration to resource IDs and attributes. Protect with encryption, locking, backups and restricted access."],["Modules & environments","Modules package reusable interfaces; validate input contracts and version module dependencies."],["Plan & policy","Review replacements/deletes, IAM/public exposure and data loss. Apply only from trusted protected workflows."]],
"terraform fmt -check -recursive; terraform init -backend=false; terraform validate; terraform plan",
"Repeatable cloud networks, compute, IAM, DNS, storage, cluster foundations and configuration management.",
"A plan is not proof of safety. Inspect replacements, data deletion, public exposure and blast radius. Protect state separately from source code.",
["Write provider constraints, variables and outputs.","Create VPC/subnets/routes/security resources.","Run fmt, init without backend and validate.","Inspect dependency graph and plan output.","Document state security, drift response and destroy controls."],
[
["What is Terraform state?","It connects resource addresses in config to real objects.","State stores bindings and attributes Terraform needs to plan changes. It may contain sensitive values and must be secured.","Safe team IaC."],
["Why not commit state to Git?","State is mutable, environment-specific and may expose secrets.","Use remote encrypted state with locking, versioning and access control; keep configuration in Git.","Collaboration and audit."],
["Resource versus data source?","One manages; one reads.","A resource manages object lifecycle; a data source reads existing infrastructure information.","Referencing existing VPC or image."],
["What does terraform plan do?","It previews actions, not applies them.","Plan compares config, state and remote attributes to show creates/updates/destroys. Review before apply.","Pull-request review."],
["Why use modules?","Think reusable interface and consistent pattern.","Modules package resources with inputs/outputs, reducing copy-paste and standardizing architecture.","VPC and app patterns."],
["Why might a resource be replaced?","Some attributes cannot be modified in place.","A force-new attribute change can require destroy/create; inspect dependencies and outage/data implications.","Database and network changes."],
["What is drift?","Live resources differ from declared or recorded state.","Drift can result from console changes or unmanaged automation. Detect with plan/refresh and reconcile intentionally.","Emergency console fixes."],
["What does terraform import do?","Bring an existing resource into state management.","Import associates an external object ID with a config address; you still need correct config and plan review.","Adopting manually created resource."],
["Why should PR pipelines not run privileged apply?","Untrusted code can alter what the apply executes.","Use constrained validation/plan for PRs and reserve apply for trusted protected branches and approvals.","Secure IaC CI."],
["What checks before destroy?","Confirm environment, data, dependencies and exact scope.","Review destroy plan, ownership, backups, dependencies and approval; verify cleanup afterwards.","Decommission."]
],
[
["Plan replaces production database","SEV-1","A parameter change causes destroy/create.","Stop apply; inspect diff, provider schema, state and dependencies.","Use in-place modification or planned migration with backup, cutover and rollback."],
["State lock remains stuck","SEV-2","Backend reports lock from interrupted operation.","Confirm no active pipeline/process owns lock; inspect lock metadata and run history.","Only force-unlock after ownership verification; validate state and re-plan."],
["Console change creates drift","SEV-3","Plan reverts security group rule from emergency fix.","Establish who changed it and whether it is still required.","Record approved change in code, remove temporary access and add drift alerts."],
["Apply partially fails","SEV-2","Some resources are created before provider error.","Inspect state and actual cloud objects; do not assume rollback.","Fix root cause, reconcile/import orphans if needed, then re-plan from current state."],
["Module default exposes storage","SEV-1","Reusable module adds public access unexpectedly.","Trace module defaults, variable values and public policy exposure.","Block exposure, assess data, set private-by-default and add policy tests."]
]),
T("cloud","10","Cloud Engineering — AWS & Multi-Cloud","ADVANCED","Design secure, resilient and cost-aware cloud systems.","Connect identity, networking, compute, storage, databases, delivery, monitoring and governance.","AWS IAM · VPC · EC2 · S3 · ALB · Route 53 · CloudWatch · ECR/ECS/EKS · Azure · GCP",
"Cloud services are building blocks, not an architecture. Learn shared responsibility, IAM, regions/AZs, network isolation, compute, storage, databases, load balancing, DNS, autoscaling, monitoring and account governance. AWS areas include roles/policies, VPC/subnets/route tables/security groups, S3, EC2, ALB, Route 53, CloudWatch, ECR, ECS and EKS. Check pricing, regional availability and account limits before provisioning.",
[["Identity & governance","Prefer roles/federation to access keys; use least privilege, MFA, audit and separate environments."],["VPC networking","Plan CIDR, public/private subnets across AZs, routes, IGW/NAT, security groups and endpoints."],["Compute & storage","Choose EC2, containers or serverless; distinguish S3 object, EBS block and EFS file storage."],["Reliability & cost","Design for AZ failure, backups, health checks, budget alerts, quotas and verified cleanup."]],
"aws sts get-caller-identity; aws s3 ls; aws ec2 describe-vpcs --region ap-south-1",
"Hosting, resilient network design, cloud identity federation, object storage, managed containers and governance.",
"A free-credit banner does not mean every service is free. Check regional pricing, NAT, load balancers, public IPv4, EBS, logs and data transfer; destroy temporary resources.",
["Draw VPC CIDR and public/private subnets.","Specify role and security-group access for each component.","Choose compute and storage with trade-offs.","Add ALB health checks, DNS and observability.","Create a cost and cleanup checklist before deployment."],
[
["IAM user versus role?","Persistent identity versus assumable temporary identity.","A user is a persistent identity; a role is assumed by trusted principals for temporary credentials. Prefer roles for workloads.","GitHub OIDC to AWS."],
["What is least privilege?","Only required actions on required resources for required time.","Narrow permissions by action, resource and condition; separate roles and review regularly.","CI deployment role."],
["What makes an AWS subnet public?","A route to an Internet Gateway is necessary but not sufficient for instance reachability.","Its route table has a path to an IGW; resources also need public addressing and suitable security controls.","VPC design."],
["How do security groups and NACLs differ?","One is stateful and attached to ENIs; one is stateless at subnet boundary.","Security groups are stateful allow rules on ENIs. NACLs are stateless subnet rules with inbound/outbound evaluation.","Network debugging."],
["What is an Availability Zone?","A fault domain within a region.","AZs isolate infrastructure failure domains. Multi-AZ design reduces dependence on one zone.","Resilient service architecture."],
["Why enable S3 versioning and lifecycle?","Think accidental overwrite recovery and retention cost.","Versioning retains object versions. Lifecycle transitions or expires data according to explicit retention and cost policies.","Artifact/log retention."],
["What does an ALB provide?","It routes application traffic to healthy targets.","An Application Load Balancer provides Layer 7 HTTP/HTTPS routing, host/path rules, TLS termination and target health.","Web app ingress."],
["Why use EC2 instance profile instead of key file?","Credentials can be provided and rotated by the platform.","Instance profiles supply temporary role credentials, avoiding long-lived credentials on disk.","App access to S3."],
["What cloud charges surprise beginners?","Look beyond compute hourly cost.","NAT, ALB, public IPv4, EBS/snapshots, managed DB, logs, data transfer and idle resources can incur charges.","Cost-safe labs."],
["What to check before deleting a cloud resource?","Consider owner, dependencies, traffic, backup and retention.","Inspect tags, dependency graph, activity, backups, DNS references, lifecycle and approval; verify after deletion.","Safe decommission."]
],
[
["IAM AccessDenied after deploy","SEV-2","App cannot read an S3 object.","Identify caller role, action/resource, bucket policy, permission boundary, SCP and KMS policy.","Add only the missing permission to workload role and retest."],
["Unexpected cloud bill","SEV-2","Spend rises after a practice environment was created.","Group by service/region/tag; inspect NAT, ALB, IPv4, snapshots, logs and transfer.","Delete confirmed unused resources safely and add budget/expiry checks."],
["EC2 unreachable","SEV-2","SSH times out after network changes.","Check instance state, route, public/private IP, IGW, security group, NACL and sshd.","Restore narrow path or use approved console access; remove temporary rule."],
["ALB targets unhealthy","SEV-1","Target group shows unhealthy and users receive 503.","Check health path, protocol/port, target registration, firewall and app readiness.","Correct health contract/runtime and test user path."],
["S3 bucket public","SEV-1","Sensitive objects may be publicly readable.","Inspect public access block, policy, ACL, logs, data class and exposure window.","Block public access, assess disclosure, rotate credentials and add guardrails."]
]),
T("gitops","11","GitOps & Progressive Delivery","ADVANCED","Make Git the auditable source of desired state.","Use pull reconciliation, environment promotion, drift detection and progressive rollout.","Argo CD · Flux · Helm · Kustomize · Argo Rollouts · Flagger",
"GitOps stores desired state in Git and uses controllers inside the environment to reconcile live systems. Learn pull-based operation, repo structure, overlays, secrets, sync health, drift and rollback. Progressive delivery adds canary or blue/green traffic control using metrics.",
[["Source of truth","Desired state lives in reviewed repository; manual cluster changes become drift."],["Pull reconciliation","An in-environment controller fetches desired state and reconciles actual objects."],["Overlays & secrets","Use Helm/Kustomize overlays and immutable image digests; never store plaintext secrets."],["Progressive delivery","Canary/blue-green uses metrics, windows and abort/promotion rules."]],
"argocd app list; argocd app get employee-api; argocd app diff employee-api; argocd app history employee-api",
"Multi-cluster delivery, audited config, environment promotion and automated drift detection.",
"Protect the config repository and production overlays. Emergency manual fixes need a documented break-glass path and must be reconciled back into Git.",
["Create base manifests and environment overlays.","Map an app to its Git source and cluster destination.","Promote one immutable image digest by reviewed commits.","Simulate live drift and inspect status.","Add canary metrics and abort/rollback criteria."],
[
["What is GitOps?","Desired state in Git plus continuous reconciliation.","A controller compares live state to reviewed Git config and reconciles the environment, creating an auditable change trail.","Kubernetes application delivery."],
["What is pull-based delivery?","The environment agent fetches desired state.","A controller in the target environment watches approved sources and applies changes, reducing CI need for direct cluster credentials.","Secure cluster delivery."],
["What is GitOps drift?","Live object differs from committed desired state.","Drift is a difference between desired and actual state; controller can report or reconcile it.","Detecting manual hotfix."],
["Why deploy by image digest?","Tags can point to changing content.","A digest identifies exact image bytes and makes promotion reproducible.","Immutable release."],
["How handle emergency manual changes?","Avoid hidden permanent drift.","Document it, time-limit the override, commit the approved desired state and verify controller convergence.","Outage break-glass process."],
["What is an environment overlay?","Environment-specific config layered over shared base.","Helm values or Kustomize overlays set replicas, endpoints, resources and policies per environment.","Dev/stage/prod."],
["Why might Argo CD not sync?","Check source access, render errors, destination permissions and policy.","Credentials, invalid manifests, ownership conflicts, sync windows or health rules can block sync.","GitOps support."],
["How does canary analysis work?","Compare canary and baseline signals before promotion.","Metric queries evaluate error, latency and saturation over a defined window; failure pauses or aborts rollout.","Progressive release."],
["Why avoid plaintext secrets in Git?","History retains secrets after later deletion.","Use external secrets or encryption; rotate values committed accidentally and assess history exposure.","Cluster credential delivery."],
["How roll back GitOps?","Revert desired state to a known-good revision.","Revert config commit or restore prior image digest; let controller converge and verify health.","Config recovery."]
],
[
["Argo app OutOfSync after hotfix","SEV-2","Live object differs from Git.","Inspect diff, audit actor and incident reason.","Record approved fix in Git and sync; restrict manual writes."],
["Controller cannot authenticate to repo","SEV-2","Repository auth errors block sync.","Check URL, credential ref, token expiry, network and controller logs.","Rotate least-privilege deploy key/token and verify read access."],
["Canary promoted during error spike","SEV-1","New version receives traffic despite failing requests.","Inspect metric query, time window, baseline and conditions.","Abort/rollback; correct thresholds and test with injected failure."],
["Secret leaked in GitOps repo","SEV-1","Plaintext key is committed and synced.","Identify key scope, commit history and cluster usage.","Revoke/rotate, remove and remediate history, move to external secret source."],
["Controller reverts emergency hotfix","SEV-2","A temporary cluster change is overwritten.","Compare desired state, ownership and current incident need.","Stabilize service, commit approved state and document break-glass controls."]
]),
T("observability","12","Observability & Telemetry","ADVANCED","Understand system behaviour from actionable signals.","Instrument metrics, logs, traces, dashboards, alerting and service objectives.","Prometheus · Grafana · OpenTelemetry · Loki · ELK · CloudWatch · Jaeger",
"Monitoring watches known conditions; observability supports investigation of unknown failure modes. Learn metrics, logs, distributed traces, cardinality, sampling, correlation IDs, dashboards, alert routing and SLOs. Alerts should be actionable and connected to user impact. Observe both infrastructure and dependencies.",
[["Metrics","Counters, gauges and histograms represent different measurements. Avoid unbounded labels."],["Logs","Structured events with timestamp, severity, service, version and correlation ID; redact sensitive data."],["Traces","Spans show request flow across services; propagate trace context and sample thoughtfully."],["Alerting & SLO","Measure user outcome, define objective and error budget; page on symptoms that require action."]],
"rate(http_requests_total[5m]); histogram_quantile(0.95, sum(rate(http_duration_bucket[5m])) by (le))",
"Incident detection, performance tuning, capacity planning, release verification and SLO reporting.",
"Every page needs owner, impact, runbook and action. Page on user impact; ticket trends. Avoid cardinality explosions that make telemetry expensive or unreliable.",
["Define availability and latency SLI.","Choose metrics and bounded label dimensions.","Emit structured logs with trace ID.","Dashboard traffic, errors, latency and saturation.","Write one actionable alert and runbook."],
[
["What are the three common signals?","Numeric trend, event record and request path.","Metrics measure values over time; logs record events; traces describe operations across service boundaries.","Distributed service diagnosis."],
["What is metric cardinality?","Count unique label combinations.","Cardinality is unique time series count; user IDs/raw URLs create dangerous unbounded values.","Prometheus design."],
["Why use histograms for latency?","An average hides tail behaviour.","Histograms aggregate latency distributions and allow percentile estimates such as p95.","SLO performance."],
["What is a correlation ID?","It links logs/events belonging to one request.","A request identifier propagated through services connects event records; trace IDs additionally link spans.","Cross-service debugging."],
["SLI versus SLO?","Measured indicator versus target.","An SLI measures outcome; SLO sets target over a defined window.","Reliability planning."],
["Why are averages misleading for latency?","A small tail of slow requests may disappear in the mean.","Track distribution percentiles and histograms alongside volume and errors.","User experience monitoring."],
["What makes an alert actionable?","Receiver should know impact and first action.","It has impact, clear threshold/window, owner, runbook and defined response.","On-call alerting."],
["What is trace sampling?","Storing every request may be expensive.","Sampling selects traces; use policy to preserve errors/slow paths and representative traffic.","Telemetry cost control."],
["When are logs better than metrics?","Detailed context versus efficient aggregate trends.","Metrics are efficient for thresholds and trends; logs provide event detail for investigation.","Alert and debug design."],
["How protect sensitive telemetry?","Logs can become a data-exfiltration channel.","Redact credentials and personal data, restrict access, encrypt and define retention.","Privacy-aware operations."]
],
[
["Alert storm","SEV-2","Hundreds of alerts fire from one upstream outage.","Group by dependency and identify common cause; inspect routing and deduplication.","Keep primary symptom page, expire duplicate silences and add grouping/inhibition."],
["Prometheus memory spike","SEV-2","New labels multiply time-series count.","Inspect cardinality, label values, scrape volume and retention.","Remove unbounded labels and add metric review tests."],
["Average latency hides tail","SEV-2","Users report slow requests while average looks normal.","Inspect p95/p99 histograms, endpoint and dependency spans.","Alert on percentile or error-budget burn and preserve slow traces."],
["Token leaked into logs","SEV-1","Debug log records bearer credential.","Identify index/time/consumers/exports and treat token as compromised.","Rotate, restrict/purge logs, add redaction and tests."],
["Dashboard green but user journey broken","SEV-1","Infra healthy but checkout fails.","Check endpoint coverage, synthetic transactions and business-flow instrumentation.","Add black-box and user journey SLIs and validate alert coverage."]
]),
T("security","13","DevSecOps & Software Supply Chain","ADVANCED","Build security into every engineering decision.","Apply threat modelling, scanning, secrets, signing, SBOMs and policy enforcement.","OWASP · SAST · DAST · SCA · Trivy · Semgrep · Vault · Cosign · OPA",
"DevSecOps embeds security into design, source, build, deploy and runtime. Learn threat modelling, IAM, secret management, SAST, DAST, SCA, IaC/container scanning, SBOMs, signing and policy-as-code. Prioritize by exploitability, reachability, exposure and business impact, not score alone.",
[["Threat modelling","Identify assets, trust boundaries, actors, attack paths and mitigations."],["Scanning layers","SAST checks source; DAST tests running app; SCA checks dependencies; IaC/image scans inspect deployment artifacts."],["Secrets & identity","Use managers, short-lived identity, rotation and audit. Never place secrets in source, image or logs."],["Provenance & policy","SBOM inventories components; signatures verify integrity/identity; policy gates enforce approved conditions."]],
"trivy fs --scanners vuln,secret,misconfig .; trivy image employee-api:1.0.0",
"Secure CI/CD, cloud identity, container hardening, compliance evidence and vulnerability response.",
"A scanner finding is not automatically a production risk; a clean scan is not proof of security. Set owners, exploitability context, expiry and verification.",
["Threat-model app trust boundaries.","Run secret, code, dependency, IaC and image scans.","Generate SBOM and analyze a vulnerable dependency.","Define signing/provenance verification.","Create exception process with owner and expiry."],
[
["SAST versus DAST?","One analyzes source; one tests a running system.","SAST analyzes code/bytecode. DAST probes a deployed application and observes runtime behaviour.","Application security test layers."],
["What does SCA find?","Think third-party components and licenses.","Software composition analysis identifies direct/transitive packages, known vulnerabilities and sometimes license policy risks.","Dependency governance."],
["What is an SBOM?","An inventory of software components.","It lists component names, versions and metadata to support vulnerability response and provenance.","CVE impact assessment."],
["Why sign images?","Digest identifies bytes, not trusted publisher.","A signature binds digest to signing identity so admission policy can verify a trusted publisher/builder.","Registry-to-cluster trust."],
["What is threat modelling?","Start with assets, boundaries, actors and abuse cases.","It systematically identifies attack paths and mitigations during design and review.","Architecture security."],
["Why are environment variables still sensitive?","They may leak through process inspection, dumps or debug output.","Restrict access and prefer runtime secret delivery; never log them or commit values.","Workload secrets."],
["How prioritize a critical vulnerability?","Consider exploitability, reachability and exposure.","Combine severity with exploit activity, vulnerable code path reachability, internet exposure, privileges and asset criticality.","Risk-based patching."],
["What is policy as code?","Rules are machine-readable and enforced repeatedly.","OPA/Conftest and cloud policy tools evaluate infrastructure/deploy decisions consistently.","Prevent public bucket or privileged Pod."],
["Why must exceptions expire?","Temporary risk can otherwise become permanent.","Record owner, scope, rationale, compensating control, review date and expiry.","Security exception governance."],
["What after a secret is committed?","Deleting the line does not invalidate the credential.","Revoke/rotate, audit use, remove active copy and address history/logs; add secret scanning.","Credential incident response."]
],
[
["Critical dependency CVE","SEV-1","Production uses vulnerable package.","Use SBOM/SCA to identify deployed versions, reachability, exposure and exploit status.","Patch/mitigate, rebuild/sign/redeploy and verify runtime version."],
["Secret scanner flags committed token","SEV-1","A workflow file contains a real credential.","Determine scope, permissions, logs and fork exposure.","Revoke first, audit, remove and add push protection."],
["Image scan blocks release","SEV-2","Base image contains a high severity package.","Check fixed version, reachability, runtime use and policy.","Update base, rebuild and retest; use only time-limited exception if needed."],
["Unsigned image admitted","SEV-1","Admission policy is disabled.","Trace image registry, digest, CI identity and deploy actor.","Quarantine/rollback; require signature/provenance verification and test deny policy."],
["Public storage created by IaC","SEV-1","A resource is exposed by insecure module default.","Identify data class, exposure time and access logs.","Block access, assess disclosure and add private-default policy tests."]
]),
T("sre","14","SRE, Reliability & Incident Management","PRODUCTION","Engineer services around measurable reliability.","Apply SLOs, incident command, resilience, capacity planning, backups and DR.","SRE · SLO · Error Budgets · PagerDuty · Chaos · Load Testing",
"SRE applies software engineering to operations. Focus on user-visible SLIs, SLOs and error budgets. Learn incident roles, severity, communication, mitigation and blameless postmortems. Design for graceful degradation, bounded retries, circuit breakers, queues, redundancy, backup/restore and disaster recovery. Reliability is an architecture and product property.",
[["SLI/SLO/error budget","Define user outcomes, target windows and allowed unreliability."],["Incident command","Assign commander, operations and communications; keep timeline and decisions."],["Resilience patterns","Use timeout budgets, bounded retries, backoff, circuit breakers, bulkheads, queues and degradation."],["Continuity","Backups need restore tests. Define RTO/RPO and track corrective work."]],
"Declare incident; assign roles; mitigate impact; verify SLI recovery; preserve timeline; complete blameless review.",
"Production on-call, capacity, incident response, disaster recovery and release risk management.",
"Restore service before assigning blame. Separate mitigation from root-cause correction; every postmortem action needs owner, due date and verification.",
["Define an SLI/SLO and error-budget impact.","Declare severity and assign roles.","Rank hypotheses based on evidence.","Choose reversible mitigation with blast-radius control.","Verify recovery and write postmortem actions."],
[
["What is an SLO?","Target for a measured service outcome.","An SLO defines a target for an SLI over a time window, such as successful valid requests per month.","Reliability objective."],
["What is an error budget?","It is the unreliability allowed by the SLO.","The error budget is tolerated failure over a window; burn rate shows how quickly it is being consumed.","Release risk decisions."],
["RTO versus RPO?","Restore time versus acceptable data loss.","RTO is target time to restore service; RPO is maximum acceptable data loss measured in time.","DR planning."],
["Why are unbounded retries dangerous?","Retries add load while the dependency is failing.","Use bounded attempts, exponential backoff with jitter and retry budgets to avoid cascading failures.","Microservice resilience."],
["What is a circuit breaker?","It temporarily stops calls to a failing dependency.","It opens after failures, short-circuits calls and probes recovery before closing.","Protect downstream services."],
["What is graceful degradation?","Keep core function working when optional components fail.","The service disables non-essential capabilities while protecting critical user journeys.","Checkout during recommendation outage."],
["What makes a postmortem blameless?","Focus on conditions and systems, not individual blame.","Reconstruct events and contributing factors, then define systemic improvements with owners.","Learning from incidents."],
["Why test backups by restoring?","A successful backup job does not prove recoverability.","Restore tests validate integrity, keys, permissions, dependencies, runbooks and RTO/RPO.","Business continuity."],
["What is a bulkhead?","Separate resource pools to contain failures.","Isolation of threads, queues or connection pools prevents one dependency starving unrelated work.","Multi-tenant service."],
["Mitigation versus root-cause correction?","One reduces current impact; one prevents recurrence.","Mitigation restores service through rollback/failover/load shed. Root-cause correction removes the defect and adds prevention.","Incident management."]
],
[
["Error budget burns after release","SEV-1","Availability drops following deployment.","Correlate burn with release, endpoints and dependencies.","Freeze risky change, roll back or mitigate, verify SLI and add regression test."],
["Database outage cascades","SEV-1","API threads and connections saturate.","Inspect pools, retries, queue depth and dependency failures.","Bound retries, shed optional load, use circuit breaker and verify recovery."],
["Backup restore fails","SEV-1","DR exercise cannot restore latest backup.","Inspect integrity, encryption key, permissions, retention and restore order.","Use last verified copy, fix pipeline and schedule measured restore drills."],
["Incident communication breaks down","SEV-2","Teams make conflicting changes without updates.","Check ownership, commander, timeline and handoff.","Assign roles, publish known facts/unknowns/next update and log decisions."],
["Capacity exhausted during spike","SEV-1","Queue depth and latency rise faster than scaling.","Inspect scaling lag, quotas, bottleneck, headroom and traffic.","Protect critical flow, add safe capacity or shed load, improve forecasting."]
]),
T("platform","15","Platform Engineering & Developer Experience","PRODUCTION","Build paved roads that help teams ship safely.","Design internal platforms, templates, catalogs, self-service APIs and guardrails.","Backstage · Crossplane · Terraform · Kubernetes · Helm · Port",
"Platform engineering creates reusable capabilities that reduce application-team cognitive load. An internal developer platform supports service creation, environments, deploy, observe and secure workflows. Learn product thinking, personas, service catalogs, templates, platform APIs, tenancy, policy and platform SLOs. The goal is not a portal; it is making the safe path the easiest path.",
[["Platform as product","Treat developers as users; measure friction and feedback."],["Golden paths","Provide secure starter templates with checks, defaults and upgrade mechanisms."],["Catalog & ownership","Track service owner, tier, dependencies, lifecycle, repo, runbook and SLO."],["Self-service guardrails","Provide approved APIs with policy, quota, audit and cost attribution."]],
"service: employee-api; owner: people-platform; tier: critical; runtime: java17; exposure: internal; observability: standard",
"Service onboarding, standard CI/CD, self-service infrastructure, compliance and platform reuse.",
"Measure time to first deploy, change failure rate, toil removed and developer satisfaction—not portal clicks alone.",
["Identify a developer persona and friction.","Define owner/tier/data metadata.","Design template with repo, CI, IaC and deployment.","Add security, cost and observability defaults.","Define adoption, upgrade and platform SLO metrics."],
[
["What is platform engineering?","An internal product of reusable delivery capabilities.","It builds self-service capabilities and paved paths so teams can safely provision, deploy and operate services.","Scaling DevOps across teams."],
["What is a golden path?","Opinionated supported route, not compulsory one-size-fits-all.","It packages proven defaults, automation and guardrails for a common use case.","Java microservice bootstrap."],
["What belongs in a service catalog?","Ownership, dependencies, lifecycle and operations references.","Owner, repo, tier, dependencies, runtime, runbook, dashboard, SLO and lifecycle state.","Incident routing."],
["Why treat platform as a product?","It has users, feedback, roadmap and reliability expectations.","Product thinking prioritizes developer outcomes, user research, adoption and support rather than tools alone.","Platform roadmap."],
["What are platform APIs?","Stable contracts for provisioning and delivery capabilities.","APIs expose environment setup, service creation and deployment behind validation, policy and audit.","Self-service provisioning."],
["Why have escape hatches?","Specialized services may need legitimate differences.","Documented exceptions allow flexibility while preserving review, policy and ownership.","Advanced workloads."],
["How measure developer experience?","Use outcomes, not portal adoption alone.","Measure time to first deploy, lead time, onboarding friction, success rate, support load and satisfaction.","Platform prioritization."],
["What is Backstage used for?","Developer portal, catalog and software scaffolder.","Backstage provides a framework for a developer portal, service catalog, templates and plugins.","Discover services and bootstrap projects."],
["How isolate platform tenants?","Separate access, resources, network and secret boundaries.","Use RBAC, namespaces/accounts, quotas, network policies, secrets and audit; UI filtering is not security.","Shared cluster."],
["What should platform team own?","Reliability of the shared capabilities teams depend on.","Own platform SLO, paved path upgrades, security defaults, support, incident response and lifecycle.","Platform operations."]
],
[
["Template creates insecure services","SEV-1","New services inherit broad IAM and public ingress.","Inspect template version, manifests, checks and generated fleet.","Fix defaults, inventory affected apps, notify owners and add conformance tests."],
["Self-service causes runaway cost","SEV-2","Teams create oversized, unowned environments.","Inspect owner/expiry tags, quota, utilization and attribution.","Pause unsafe template, add quota/TTL and review expensive requests."],
["Service catalog ownership stale","SEV-2","Incident pages former owner.","Compare metadata with CODEOWNERS and deployment source.","Automate ownership sync and enforce freshness checks."],
["Template upgrade breaks apps","SEV-2","Generated app fails after template change.","Identify template version, compatibility and impacted cohorts.","Version templates, publish migration guide and test upgrade paths."],
["Platform API bottleneck","SEV-2","Provision requests queue during busy hours.","Inspect latency, queue depth, dependencies and tenant contention.","Restore capacity, add backpressure and establish API SLO."]
]),
T("aiops","16","AI, AIOps, MLOps & LLMOps","EMERGING → PRODUCTION","Use AI safely across engineering, delivery and operations.","Understand AI/ML/GenAI and build secure, evaluated, observable AI-assisted workflows.","Python · scikit-learn · PyTorch · LLMs · RAG · Agents · MCP · MLflow · Kubeflow",
"AI in DevOps has two sides: using AI to assist engineers and operating AI systems as production workloads. Learn ML lifecycle, supervised/unsupervised learning, features, training/inference and drift. For GenAI understand tokens, context windows, embeddings, vector search, RAG, tool use, agents and evaluation. LLMOps adds prompt/model versioning, privacy, latency/cost budgets, safety, monitoring and rollback. AI output is probabilistic and must not bypass review.",
[["AI & ML foundations","AI is broad; ML learns patterns from data. Supervised uses labels; unsupervised finds structure; inference applies a trained model."],["LLMs & prompts","LLMs predict tokens from context. Token count, context window and prompt structure affect cost and reliability."],["Embeddings & RAG","Embeddings represent semantic features. RAG retrieves authorized relevant sources and supplies them to a model."],["Agents & LLMOps","Agents use tools in bounded loops. Monitor quality, retrieval, safety, latency, cost and model/prompt version."]],
"Retrieve approved runbook; summarize telemetry with citations; suggest read-only diagnostics; human verifies; approved changes use normal CI/CD.",
"Incident summarization, log clustering, CI failure explanation, anomaly detection, knowledge retrieval, test generation and developer portals.",
"Never give an LLM unrestricted production credentials or shell. Treat retrieved text as untrusted, enforce authorization outside the model, audit tools and require human approval for mutations.",
["Define a narrow assistant use case and evaluation set.","Create approved runbook corpus with source metadata.","Design retrieval and source citations.","Expose read-only schema-validated tools.","Add prompt-injection, privacy, cost and latency tests."],
[
["AI versus ML versus generative AI?","Think broad discipline, learned patterns and content generation.","AI is the broad discipline. ML learns patterns from data. Generative AI produces content such as text, code or images.","Anomaly detection versus LLM assistant."],
["What is an LLM token?","It is a model-specific text unit, not always a whole word.","Tokens represent text and determine context use, latency and cost.","Prompt sizing and budgets."],
["What is an embedding?","A vector representation of semantic features.","Embeddings map content to vectors where semantically related items may be close.","Runbook similarity search."],
["What is RAG?","Retrieve evidence before generating an answer.","Retrieval-augmented generation finds relevant authorized documents and supplies context to the model.","Internal documentation assistant."],
["Does RAG guarantee factual answers?","Retrieval may be stale, wrong or incomplete.","No. The model can misread context or hallucinate. Require citations, abstention, evaluation and freshness.","Grounded troubleshooting assistant."],
["What is prompt injection?","Untrusted content attempts to alter intended tool/model behaviour.","Malicious or accidental instructions in user/retrieved data try to override policy. Treat external content as data and authorize tools outside the model.","Secure RAG and agents."],
["Assistant versus agent?","Consider whether it plans and invokes tools in a loop.","An agent can choose tools and iterate; an assistant may only respond. Tool use needs bounded permissions and audit.","Incident automation."],
["What is model drift?","Incoming data or outcome relationships change.","Data drift changes input distribution; concept drift changes target relationships. Monitor and validate before retraining.","Predictive maintenance."],
["What should production LLM monitoring include?","Track task quality in addition to infrastructure health.","Monitor groundedness, safety, latency, availability, token/cost, retrieval, tool errors and version.","LLMOps dashboard."],
["Why review AI-generated shell or IaC?","Plausible output can still be destructive or wrong.","Validate syntax, scope, identity, plan and side effects in a safe environment before execution.","AI coding copilot."]
],
[
["Agent proposes destructive command","SEV-1","Assistant recommends deleting resources from misleading evidence.","Block execution; inspect evidence, tool permission and approval boundary.","Read-only by default, allow-list operations and require human approval for mutation."],
["RAG cites obsolete runbook","SEV-2","Suggested endpoint is retired.","Inspect owner, revision date, retrieval ranking and index freshness.","Archive stale source, add freshness metadata and re-index."],
["Prompt injection appears in logs","SEV-1","A log entry instructs model to reveal secrets or call privileged tools.","Treat log content as untrusted and inspect any tool calls.","Separate tool permissions from model text, test injection and audit actions."],
["LLM cost and latency spike","SEV-2","Token count rises after prompt update.","Compare request volume, context size, retrieval payload, retries and model version.","Roll back prompt, cap tokens/retries, cache safely and add budget alerts."],
["Anomaly model false positives surge","SEV-2","Prediction quality falls after platform migration.","Compare feature distributions, labels, model version and downstream impact.","Fallback to safe rules, label new data and evaluate retraining offline."]
]),
T("finops","17","FinOps, Governance & Cost Optimization","PRODUCTION","Make cost a measurable engineering quality attribute.","Attribute spend, optimize waste, forecast capacity and preserve reliability.","AWS Cost Explorer · Budgets · Infracost · OpenCost · Kubecost · Tags",
"FinOps aligns engineering, finance and business to maximize cloud value. Learn allocation, tags, budgets, unit economics, rightsizing, autoscaling, storage lifecycle, data transfer and Kubernetes cost visibility. Cost optimization must preserve security and reliability. Make cost visible in design and CI, then continuously identify unused resources and anomalous spend.",
[["Allocation","Use tags/accounts/projects to attribute cost and measure unit economics."],["Optimization","Rightsize, autoscale, schedule non-prod, delete waste and optimize data transfer/storage."],["Governance","Budgets alert but may not stop spend. Define owners, escalation and cleanup."],["Reliability trade-offs","Do not remove backups or redundancy blindly; compare savings with risk and recovery targets."]],
"Estimate services/region/hours/storage/transfer; tag owner and expiry; configure alerts; define cleanup; verify all resources gone.",
"Cloud bill safety, forecasting, Kubernetes allocation, ephemeral environments and architecture cost decisions.",
"Cost optimization is not simply turning services off. Tie spend to service value, SLO, ownership and risk.",
["Inventory environment resources with owner and expiry.","Estimate major service and data-transfer costs.","Define budget thresholds and recipients.","Add policy/IaC cost checks and scheduling.","Write cleanup and exception checklist."],
[
["Why are budgets not always hard spending limits?","An alert may arrive after resource use has occurred.","Budgets usually notify; they do not prevent all consumption. Add quotas, policy controls and cleanup automation.","Unexpected bill prevention."],
["Why use resource tags?","They answer who owns a resource and why it exists.","Tags support showback, inventory, cleanup, policy and owner notification.","Finding orphaned resources."],
["What is rightsizing?","Match capacity to measured demand and headroom.","Adjust compute/storage/database capacity from utilization and performance evidence without harming SLO.","EC2/database optimization."],
["Why can network transfer dominate spend?","Traffic across regions, zones or the public internet may be billed.","Transfer, NAT processing and cross-AZ traffic can add large costs; design placement and egress intentionally.","Distributed service design."],
["What is unit economics?","Relate cost to a business or workload unit.","Measure cost per request, transaction, customer, build or environment.","Cost efficiency trends."],
["Why add expiry tags to practice environments?","Temporary labs are easily forgotten.","TTL tags enable owner notification and scheduled cleanup with a controlled exception path.","Learning lab lifecycle."],
["How optimize Kubernetes cost?","Inspect requests, utilization, node packing and idle capacity.","Right-size requests, use bin packing/autoscaling, remove unused workloads and allocate shared costs fairly.","Cluster operations."],
["What cost risks exist in beginner AWS labs?","Look beyond compute hours.","NAT, ALB, public IPv4, EBS/snapshots, databases, logs and data transfer can cost money; check region and current eligibility.","Cost-safe cloud practice."],
["Showback versus chargeback?","One reports; the other financially assigns.","Showback makes team spend visible; chargeback assigns it to budgets or cost centers.","FinOps model."],
["How handle a cost anomaly?","Confirm usage and ownership before deleting.","Find service/region/time/resource owner, assess dependencies and data retention, contain runaway spend safely and add guardrails.","Unexpected cost investigation."]
],
[
["Idle NAT gateways continue spending","SEV-2","Practice VPC remains deployed with no app traffic.","Review cost by region/service and gateway route dependencies.","Delete only after dependency check; verify routes and set expiry/budget."],
["Lifecycle rule expires needed data","SEV-1","Storage policy removes required recovery objects.","Stop policy, inspect versions/retention/legal hold and restore options.","Restore verified data, narrow policy and add lifecycle tests/approval."],
["Autoscaling increases cost rapidly","SEV-2","Bad metric drives fleet to maximum size.","Inspect metric units, threshold, request rate and scaling activity.","Stabilize capacity, correct metric/cooldown and add anomaly alert."],
["Orphaned snapshots and IPs","SEV-3","Spend continues after project shutdown.","Inventory tags, creation dates, dependencies and ownership.","Notify owner, approve deletion and enforce expiry tags at creation."],
["Cost saving threatens availability","SEV-1","Team removes multi-AZ capacity to meet budget.","Review criticality, SLO, RTO/RPO and risk acceptance.","Restore required reliability and find savings elsewhere; document risk exception."]
])
];